1	"use server";
2	
3	/**
4	 * Restores an archived project.
5	 *
6	 * Owner D. There is no `restoreProjectSchema` in `src/schemas` because the
7	 * payload is nothing but the two ids, so the shape is composed here from the
8	 * shared branded-id primitives rather than added to the frozen schema layer.
9	 *
10	 * Must call (do not reimplement): can, restorePatch, getActor, toActionResult
11	 */
12	
13	import { ActionNotFoundError, ForbiddenActionError } from "@/actions/_lib/action-errors";
14	import { withAction } from "@/actions/_lib/with-action";
15	import { CACHE_PROFILES, orgTag, projectTag, revalidateTagged } from "@/lib/cache";
